const clone=o=>JSON.parse(JSON.stringify(o)),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function lang(){const x=(Device.locale()||"en").slice(0,2).toLowerCase();return["cs","en","de","es"].includes(x)?x:"en"}
function tx(s,k){const x=s.language||lang();return(L[x]||L.en)[k]||L.en[k]||k}
