function merge(raw){const s=Object.assign(clone(DEFAULTS),raw||{});if(!["cs","en","de","es"].includes(s.language))s.language=null;if(!SPORTS.some(x=>x.id===s.sportId))s.sportId=DEFAULTS.sportId;const a=leaguesForSport(s.sportId);if(!a.some(x=>x.id===s.leagueId))s.leagueId=a[0]?.id||DEFAULTS.leagueId;s.maxMatches=clamp(Number(s.maxMatches)||4,1,8);s.refreshMinutes=clamp(Number(s.refreshMinutes)||15,5,60);if(!["auto","dark","light","custom"].includes(s.theme))s.theme="auto";for(const k of["accent","background","panelColor","textColor","mutedColor","liveColor","winColor"])if(!/^#[0-9a-fA-F]{6}$/.test(String(s[k]||"")))s[k]=DEFAULTS[k];for(const k of["apiEspnBase","apiFotmobBase","apiOneFootballFeedBase","apiOneFootballScoresBase"])s[k]=String(s[k]||DEFAULTS[k]).replace(/\/+$/,"");return s}
function loadSettings(){try{if(fm.fileExists(settingsPath))return merge(JSON.parse(fm.readString(settingsPath)));if(fm.fileExists(legacySettingsPath)){const s=merge(Object.assign({sportId:"football"},JSON.parse(fm.readString(legacySettingsPath))));saveSettings(s);return s}}catch(e){console.log(e)}return clone(DEFAULTS)}
function saveSettings(s){try{fm.writeString(settingsPath,JSON.stringify(merge(s),null,2))}catch(e){console.log(e)}}
async function firstLanguage(s){if(s.language)return s;if(config.runsInWidget){s.language=lang();saveSettings(s);return s}const a=new Alert();a.title=APP_NAME;a.message="Choose language / Vyber jazyk";["🇨🇿 Čeština","🇬🇧 English","🇩🇪 Deutsch","🇪🇸 Español"].forEach(x=>a.addAction(x));const i=await a.presentAlert();s.language=["cs","en","de","es"][Math.max(0,i)]||"en";saveSettings(s);return s}

function dateKey(d){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,"0"),z=String(d.getDate()).padStart(2,"0");return`${y}${m}${z}`}
function range(a,b){const x=new Date(),y=new Date();x.setDate(x.getDate()+a);y.setDate(y.getDate()+b);return`${dateKey(x)}-${dateKey(y)}`}
async function requestJSON(url,headers=null){const r=new Request(url);r.timeoutInterval=API_TIMEOUT;if(headers)r.headers=headers;return await r.loadJSON()}
async function requestText(url,headers=null){const r=new Request(url);r.timeoutInterval=API_TIMEOUT;if(headers)r.headers=headers;return await r.loadString()}
const BROWSER_HEADERS={"User-Agent":"Mozilla/5.0 (iPhone; CPU iPhone OS like Mac OS X) AppleWebKit/605.1.15 Mobile/15E148","Accept":"application/json,text/plain,*/*","Accept-Language":"en-US,en;q=0.9,cs;q=0.8"};
