function clean(v){return v==null?"":String(v)}
function unique(a){const m=new Map();for(const e of a||[])if(e?.id)m.set(e.id,e);return[...m.values()].sort((x,y)=>new Date(x.date)-new Date(y.date))}
function pctValue(v,w,p){if(v!==""&&v!=null){const n=Number(v);if(Number.isFinite(n))return n.toFixed(3)}if(Number(p)>0&&Number.isFinite(Number(w)))return(Number(w)/Number(p)).toFixed(3);return""}
function row(x={}){const score=x.score||((x.for!==""||x.against!=="")?`${clean(x.for)||"–"}:${clean(x.against)||"–"}`:"");return{rank:Number(x.rank)||0,id:clean(x.id),name:clean(x.name),short:clean(x.short||x.name),logo:clean(x.logo),played:clean(x.played),wins:clean(x.wins),draws:clean(x.draws),losses:clean(x.losses),otWins:clean(x.otWins),otLosses:clean(x.otLosses),points:clean(x.points),pct:pctValue(x.pct,x.wins,x.played),gb:clean(x.gb),for:clean(x.for),against:clean(x.against),score:clean(score),diff:clean(x.diff)}}
function team(x={}){return{id:clean(x.id),name:clean(x.name),short:clean(x.short||x.abbr||x.name),abbr:clean(x.abbr),logo:clean(x.logo)}}
function event(e={}){return{id:clean(e.id),date:clean(e.date),state:e.state==="in"?"in":e.completed||e.state==="post"?"post":"pre",completed:!!e.completed||e.state==="post",status:clean(e.status),home:Object.assign(team(e.home),{score:clean(e.home?.score)}),away:Object.assign(team(e.away),{score:clean(e.away?.score)})}}
function teamsFrom(events,rows=[]){const m=new Map();for(const r of rows||[])if(r.id&&r.name)m.set(String(r.id),team(r));for(const e of events||[])for(const t of[e.home,e.away])if(t?.id&&t?.name)m.set(String(t.id),team(t));return[...m.values()].sort((a,b)=>a.name.localeCompare(b.name))}
function inRange(e,dates){if(!dates||!e?.date)return true;const p=String(dates).split("-"),k=dateKey(new Date(e.date));return p.length<2?k===p[0]:(k>=p[0]&&k<=p[1])}
function normName(v){try{return String(v||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim()}catch(_){return String(v||"").toLowerCase()}}
function teamMatches(t,s){if(!t)return false;if(s.teamId&&String(t.id||"")===String(s.teamId))return true;const a=normName(t.name||t.short),b=normName(s.teamName);return!!b&&(a===b||a.includes(b)||b.includes(a))}
function eventMatches(e,s){return teamMatches(e?.home,s)||teamMatches(e?.away,s)}

function espnStat(stats,names,f=""){const wanted=names.map(x=>String(x).toLowerCase());for(const x of stats||[]){const n=String(x.name||x.type||x.abbreviation||"").toLowerCase();if(wanted.includes(n))return x.value??x.displayValue??f}return f}
function standingsEntries(o){const out=[],seen=new Set();const walk=x=>{if(!x||typeof x!=="object")return;if(Array.isArray(x.entries))for(const e of x.entries){const id=String(e?.team?.id||"");if(id&&!seen.has(id)){seen.add(id);out.push(e)}}for(const k of["children","groups"])if(Array.isArray(x[k]))for(const y of x[k])walk(y);if(x.standings&&typeof x.standings==="object")walk(x.standings)};walk(o);return out}
