function formRow(parent,s,d,p){if(!(s.teamId||s.teamName)||!d.form.length)return;const r=parent.addStack();r.layoutHorizontally();txt(r,tx(s,"form")+":",9,p.muted,true);r.addSpacer(6);for(const x of d.form){txt(r,x,9,x==="W"?p.ok:(x==="L"||x==="OTL")?p.live:p.muted,true);r.addSpacer(4)}r.addSpacer()}
function tableValue(r,key){if(key==="team")return r.name||r.short||"";return r?.[key]!==""&&r?.[key]!=null?String(r[key]):"–"}
function tableRows(s,d,maxRows){const all=d.table||[];if(all.length<=maxRows)return all;const fav=(s.teamId||s.teamName)?all.findIndex(x=>teamMatches(x,s)):-1;if(fav<0)return all.slice(0,maxRows);const start=Math.max(0,Math.min(fav-Math.floor(maxRows/2),all.length-maxRows));return all.slice(start,start+maxRows)}
function renderTable(parent,s,d,p,maxRows){if(!d.table.length)return;const rows=tableRows(s,d,Math.min(maxRows,d.table.length)),cols=d.columns;title(parent,tx(s,"table"),p);parent.addSpacer(3);const h=parent.addStack();h.layoutHorizontally();for(const [key,label,width] of cols)cell(h,label,width,p,key==="team"?"left":"center",true,7,p.muted);parent.addSpacer(2);for(const r0 of rows){const fav=(s.teamId||s.teamName)&&teamMatches(r0,s),r=parent.addStack();r.layoutHorizontally();r.centerAlignContent();for(const [key,,width] of cols){const t=cell(r,tableValue(r0,key),width,p,key==="team"?"left":"center",fav,8,fav?p.accent:(key==="team"?p.text:p.muted));if(key==="team")t.minimumScaleFactor=.45}}}
function tableCapacity(s,d){if(s.fullTableLarge)return 20;let n=d.current?8:16;if(s.showNext&&d.next.length)n-=2;if(s.showLast&&d.done.length)n-=2;return Math.max(5,n)}
async function widget(s,family){const d=await SportsAPI.load(s),p=pal(s),w=new ListWidget();w.backgroundColor=p.bg;w.setPadding(s.compact?9:12,s.compact?9:12,s.compact?9:12,s.compact?9:12);w.refreshAfterDate=new Date(Date.now()+s.refreshMinutes*60000);const h=w.addStack();h.layoutHorizontally();h.centerAlignContent();txt(h,sport(s).icon,14,p.text,true);h.addSpacer(5);txt(h,`${league(s).flag||""} ${leagueName(s)}`.trim(),family==="small"?10:12,p.text,true);h.addSpacer();txt(h,d.source==="cache"?tx(s,"cache"):d.source==="error"?tx(s,"error"):d.live.length?tx(s,"liveNow"):String(d.providers?.matches||"DATA").toUpperCase(),8,d.live.length?p.live:d.source==="error"?p.live:p.accent,true);w.addSpacer(s.compact?5:8);if(s.fullTableLarge&&family==="large"&&s.showTable&&d.table.length){renderTable(w,s,d,p,tableCapacity(s,d));return w}if(!d.current){const b=w.addStack();b.backgroundColor=p.panel;b.cornerRadius=14;b.setPadding(12,12,12,12);txt(b,tx(s,"noData"),11,p.text,true);if(family==="large"&&s.showTable&&d.table.length){w.addSpacer(8);renderTable(w,s,d,p,16)}return w}await matchCard(w,d.current,s,p,family);if(s.showForm&&(s.teamId||s.teamName)){w.addSpacer(5);formRow(w,s,d,p)}if(family==="small")return w;const upcoming=s.showNext?d.next.filter(x=>x.id!==d.current.id).slice(0,family==="large"&&s.showTable?Math.min(s.maxMatches,2):family==="large"?s.maxMatches:2):[];if(upcoming.length){w.addSpacer(7);title(w,tx(s,"next"),p);w.addSpacer(3);for(const e of upcoming){await matchLine(w,e,s,p,family);if(family==="large")w.addSpacer(1)}}if(family==="large"&&s.showLast&&d.done.length){w.addSpacer(7);title(w,tx(s,"last"),p);w.addSpacer(3);for(const e of d.done.filter(x=>x.id!==d.current.id).slice(0,s.showTable?Math.min(s.maxMatches,2):s.maxMatches)){await matchLine(w,e,s,p,family);w.addSpacer(1)}}if(family==="large"&&s.showTable&&d.table.length){w.addSpacer(7);renderTable(w,s,d,p,tableCapacity(s,d))}if(family==="large"){w.addSpacer();const f=w.addStack();f.addSpacer();txt(f,`${tx(s,"updated")}: ${new Date(d.at).toLocaleTimeString(s.language||"en",{hour:"2-digit",minute:"2-digit"})}`,8,p.muted);f.addSpacer()}return w}

function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function opt(v,l,sel){return`<option value="${esc(v)}" ${sel?"selected":""}>${esc(l)}</option>`}
function sw(id,label,on){return`<label class="row"><span>${esc(label)}</span><input id="${id}" type="checkbox" ${on?"checked":""}></label>`}
function color(id,label,value){return`<label class="field"><span>${esc(label)}</span><input id="${id}" type="color" value="${esc(value)}"></label>`}
function settingsHTML(s){const U=L[s.language||"en"]||L.en,spOpts=SPORTS.map(x=>opt(x.id,`${x.icon} ${x[s.language]||x.en}`,x.id===s.sportId)).join(""),lgOpts=leaguesForSport(s.sportId).map(x=>opt(x.id,`${x.flag||""} ${x[s.language]||x.en}`,x.id===s.leagueId)).join(""),teamOpt=s.teamId?opt(s.teamId,s.teamName||s.teamId,true):opt("",U.whole,true);return`<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><style>:root{color-scheme:dark;--bg:#070b14;--p:#111827;--b:#2a3850;--t:#f8fafc;--m:#94a3b8;--a:${s.accent};--ok:#86efac;--bad:#fb7185}*{box-sizing:border-box}body{margin:0 auto;max-width:680px;background:radial-gradient(circle at top,#172554,#0b1020 42%,#070b14);color:var(--t);font-family:system-ui;padding:calc(14px + env(safe-area-inset-top)) 14px 36px}.hero,.card{background:rgba(17,24,39,.97);border:1px solid var(--b);border-radius:18px;margin-bottom:13px;overflow:hidden}.hero{padding:20px}.hero h1{margin:8px 0 4px;font-size:28px}.muted,small{color:var(--m)}.sec{font-size:11px;text-transform:uppercase;letter-spacing:.1em;color:#9fb3ce;font-weight:800;margin:18px 8px 7px}.row,.field{min-height:52px;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 14px;border-bottom:1px solid var(--b)}.row:last-child,.field:last-child{border:0}.field{display:block}.field span{display:block;font-size:12px;color:#dbeafe;margin-bottom:7px}select,input[type=number],textarea{width:100%;min-height:42px;border:1px solid var(--b);border-radius:11px;background:#0b1220;color:var(--t);padding:0 10px;font:inherit}input[type=checkbox]{width:22px;height:22px;accent-color:var(--a)}input[type=color]{width:58px;height:38px;border:0;background:transparent}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:13px}button{min-height:44px;border:1px solid #1d4ed8;border-radius:12px;background:linear-gradient(135deg,#0369a1,#0284c7);color:white;font:inherit;font-weight:800;padding:8px}.secondary{background:#243149;border-color:var(--b)}.danger{background:#3a1720;border-color:#6b2738}.diag{padding:10px 12px;border-bottom:1px solid var(--b)}.diag:last-child{border:0}.diag b,.diag small{display:block}.diag.ok b{color:var(--ok)}.diag.bad b{color:var(--bad)}textarea{min-height:150px;padding:10px;font-family:ui-monospace,monospace;font-size:11px}.status{min-height:18px;color:var(--m);font-size:12px;margin:6px 2px}.two{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:10px}@media(max-width:420px){.grid{grid-template-columns:1fr}.two{grid-template-columns:1fr}}</style></head><body><div class="hero"><div class="muted">🏆 Scriptable · v${APP_VERSION}</div><h1>Sports Info</h1><div class="muted">Online data → widget. No season archive.</div><div style="height:10px"></div><button class="secondary" onclick="updateApp()">↻ Update</button><div id="updateStatus" class="status"></div></div><div class="sec">${esc(U.preview)}</div><div class="grid"><button onclick="preview('small')">Small</button><button onclick="preview('medium')">Medium</button><button onclick="preview('large')">Large</button></div><div class="sec">Sport</div><div class="card"><label class="field"><span>Sport</span><select id="sportId">${spOpts}</select></label><label class="field"><span>Competition</span><select id="leagueId">${lgOpts}</select></label><label class="field"><span>Team</span><select id="teamId">${teamOpt}</select><div style="height:8px"></div><button style="width:100%" onclick="loadTeams()">↻ ${esc(U.loadTeams)}</button><div id="teamStatus" class="status"></div></label></div><div class="sec">Widget</div><div class="card">${sw("showLive",U.live,s.showLive)}${sw("showNext",U.next,s.showNext)}${sw("showLast",U.last,s.showLast)}${sw("showTable",U.table,s.showTable)}${sw("showForm",U.form,s.showForm)}${sw("showLogos",U.logos,s.showLogos)}${sw("fullTableLarge",U.fullTable,s.fullTableLarge)}<label class="field"><span>Max matches</span><input id="maxMatches" type="number" min="1" max="8" value="${s.maxMatches}"></label></div><div class="sec">${esc(U.appearance)}</div><div class="card"><label class="field"><span>${esc(U.theme)}</span><select id="theme">${["auto","dark","light","custom"].map(x=>opt(x,U[x]||x,s.theme===x)).join("")}</select></label>${sw("compact",U.compact,s.compact)}<label class="field"><span>${esc(U.refresh)}</span><input id="refreshMinutes" type="number" min="5" max="60" value="${s.refreshMinutes}"></label>${color("accent","Accent",s.accent)}${color("background","Background",s.background)}${color("panelColor","Panel",s.panelColor)}${color("textColor","Text",s.textColor)}${color("mutedColor","Muted",s.mutedColor)}${color("liveColor","Live/Loss",s.liveColor)}${color("winColor","Win",s.winColor)}</div><div class="sec">${esc(U.diagnostics)}</div><div class="grid"><button onclick="diagCurrent()">🧪 ${esc(U.diagCurrent)}</button><button onclick="diagAll()">🌐 ${esc(U.diagAll)}</button><button class="secondary" onclick="clearDiag()">✕</button></div><div id="diagList" class="card"></div><div class="sec">${esc(U.maintenance)}</div><div class="card"><label class="field"><span>JSON</span><textarea id="jsonBox"></textarea></label><div class="two"><button onclick="exportJSON()">📤 ${esc(U.export)}</button><button class="secondary" onclick="importJSON()">📥 ${esc(U.import)}</button><button class="secondary" onclick="clearCache()">🧹 ${esc(U.clearCache)}</button><button class="danger" onclick="resetAll()">↺ ${esc(U.reset)}</button></div><div id="status" class="status" style="padding:0 10px 10px"></div></div><script>const UI=${JSON.stringify(U)},CAT=${JSON.stringify(SPORTS)};let state=${JSON.stringify(s)},timer=null;window.__q=[];function emit(action,p={}){window.__q.push({action,...p,n:Date.now()+Math.random()})}function leagues(id){return(CAT.find(x=>x.id===id)||CAT[0]).leagues||[]}function collect(){const z={...state};for(const id of['sportId','leagueId','theme','accent','background','panelColor','textColor','mutedColor','liveColor','winColor']){const e=document.getElementById(id);if(e)z[id]=e.value}for(const id of['maxMatches','refreshMinutes']){const e=document.getElementById(id);if(e)z[id]=Number(e.value)}for(const id of['showLive','showLast','showNext','showTable','showForm','showLogos','fullTableLarge','compact']){const e=document.getElementById(id);if(e)z[id]=e.checked}const t=document.getElementById('teamId');if(t){z.teamId=t.value;z.teamName=t.value?(t.options[t.selectedIndex]?.text||''):''}return z}function save(){clearTimeout(timer);timer=setTimeout(()=>{state=collect();emit('save',{settings:state})},100)}function resetTeam(){const t=document.getElementById('teamId');t.innerHTML='<option value="">'+UI.whole+'</option>';state.teamId='';state.teamName=''}document.getElementById('sportId').onchange=()=>{const id=document.getElementById('sportId').value,l=document.getElementById('leagueId');l.innerHTML='';leagues(id).forEach(x=>{const o=document.createElement('option');o.value=x.id;o.textContent=(x.flag||'')+' '+(x[state.language]||x.en||x.id);l.appendChild(o)});resetTeam();save()};document.getElementById('leagueId').onchange=()=>{resetTeam();save()};document.querySelectorAll('input,select').forEach(x=>x.addEventListener('change',save));function preview(f){emit('preview',{family:f,settings:collect()})}function loadTeams(){document.getElementById('teamStatus').textContent=UI.loading;emit('teams',{settings:collect()})}function diagCurrent(){document.getElementById('diagList').innerHTML='<div class="diag"><b>'+UI.loading+'</b></div>';emit('diagCurrent',{settings:collect()})}function diagAll(){document.getElementById('diagList').innerHTML='';emit('diagAll',{settings:collect()})}function clearDiag(){document.getElementById('diagList').innerHTML=''}function exportJSON(){emit('export',{settings:collect()})}function importJSON(){emit('import',{raw:document.getElementById('jsonBox').value})}function clearCache(){emit('clearCache',{})}function resetAll(){emit('reset',{})}function updateApp(){document.getElementById('updateStatus').textContent=UI.loading;emit('update',{settings:collect()})}function renderDiag(r,append=false){const box=document.getElementById('diagList');if(!append)box.innerHTML='';const d=document.createElement('div');d.className='diag '+(r.ok?'ok':'bad');const b=document.createElement('b'),a=document.createElement('small'),c=document.createElement('small'),e=document.createElement('small');b.textContent=r.name||'';a.textContent=r.source||'';c.textContent='👥 '+(r.teams||0)+' · 🎮 '+(r.matches||0)+' ('+(r.live||0)+'/'+(r.previous||0)+'/'+(r.upcoming||0)+') · 📊 '+(r.rows||0);e.textContent=(r.columns||'')+(r.error?' · '+r.error:'');d.append(b,a,c,e);box.appendChild(d)}window.__native=function(m){if(!m)return;if(m.action==='teams'){const t=document.getElementById('teamId');t.innerHTML='<option value="">'+UI.whole+'</option>';(m.teams||[]).forEach(x=>{const o=document.createElement('option');o.value=x.id;o.textContent=x.name;if(x.id===state.teamId)o.selected=true;t.appendChild(o)});document.getElementById('teamStatus').textContent=m.ok?UI.ok:UI.error}if(m.action==='diag')renderDiag(m.row,!!m.append);if(m.action==='status')document.getElementById('status').textContent=m.text||'';if(m.action==='update')document.getElementById('updateStatus').textContent=m.text||'';if(m.action==='replace'){state=m.settings;location.reload()}};</script></body></html>`}
async function send(web,o){try{await web.evaluateJavaScript(`window.__native(${JSON.stringify(o)})`,false)}catch(_){}}
async function settings(s){const web=new WebView();await web.loadHTML(settingsHTML(s));let dismissed=false;const presented=web.present(false).then(()=>dismissed=true),sleep=ms=>new Promise(r=>Timer.schedule(ms,false,r));let cur=merge(s);while(!dismissed){await sleep(150);let raw=null;try{raw=await web.evaluateJavaScript("JSON.stringify(window.__q.shift()||null)")}catch(_){continue}if(!raw||raw==="null")continue;let m;try{m=JSON.parse(raw)}catch(_){continue}try{if(m.action==="save"){cur=merge(m.settings);saveSettings(cur)}else if(m.action==="teams"){cur=merge(m.settings||cur);saveSettings(cur);const r=await firstFrom(cur,"teams");await send(web,{action:"teams",ok:!!r.value.length,teams:r.value})}else if(m.action==="preview"){cur=merge(m.settings||cur);saveSettings(cur);const f=["small","medium","large"].includes(m.family)?m.family:"medium",base=URLScheme.forRunningScript(),sep=base.includes("?")?"&":"?";Safari.open(base+`${sep}sportsPreview=${encodeURIComponent(f)}`);return cur}else if(m.action==="diagCurrent"){cur=merge(m.settings||cur);saveSettings(cur);await send(web,{action:"diag",row:await diagnosticsFor(cur),append:false})}else if(m.action==="diagAll"){cur=merge(m.settings||cur);saveSettings(cur);let first=true;await diagnosticsAll(cur,async r=>{await send(web,{action:"diag",row:r,append:!first});first=false})}else if(m.action==="export"){cur=merge(m.settings||cur);saveSettings(cur);Pasteboard.copyString(JSON.stringify(cur,null,2));await send(web,{action:"status",text:tx(cur,"copied")})}else if(m.action==="import"){try{cur=merge(JSON.parse(m.raw||""));if(!cur.language)cur.language=s.language||lang();saveSettings(cur);await send(web,{action:"status",text:tx(cur,"imported")});await send(web,{action:"replace",settings:cur})}catch(_){await send(web,{action:"status",text:tx(cur,"invalid")})}}else if(m.action==="clearCache"){try{if(fm.fileExists(cachePath))fm.remove(cachePath)}catch(_){}await send(web,{action:"status",text:tx(cur,"cacheCleared")})}else if(m.action==="reset"){const l=cur.language||lang();cur=clone(DEFAULTS);cur.language=l;saveSettings(cur);await send(web,{action:"replace",settings:cur})}else if(m.action==="update"){cur=merge(m.settings||cur);saveSettings(cur);const r=await updater(cur);await send(web,{action:"update",text:r.text})}}catch(e){await send(web,{action:"status",text:String(e)})}}try{await presented}catch(_){}return cur}
function versionParts(v){const[core,pre=""]=String(v||"0").split("-",2);return{n:core.split(".").map(x=>Number(x)||0),pre}}
function cmpVersion(a,b){const A=versionParts(a),B=versionParts(b),n=Math.max(A.n.length,B.n.length);for(let i=0;i<n;i++){if((A.n[i]||0)!==(B.n[i]||0))return(A.n[i]||0)>(B.n[i]||0)?1:-1}if(A.pre===B.pre)return 0;if(!A.pre)return 1;if(!B.pre)return-1;return A.pre>B.pre?1:-1}
async function updater(s){try{const src=await requestText(UPDATE_SOURCE_URL,BROWSER_HEADERS);if(!src||src.length<UPDATE_MIN_BYTES)throw new Error("Bad source");const m=src.match(/const APP_VERSION\s*=\s*"([^"]+)"/);if(!m)throw new Error("No version");const v=m[1];if(cmpVersion(v,APP_VERSION)<=0)return{ok:true,text:`v${APP_VERSION} · current`};const a=new Alert();a.title=APP_NAME;a.message=`v${APP_VERSION} → v${v}`;a.addAction("Update");a.addCancelAction("Cancel");if(await a.presentAlert()!==0)return{ok:true,text:`v${APP_VERSION} → v${v}`};const target=module.filename,b=fm.joinPath(fm.documentsDirectory(),`SportsInfo_backup_v${APP_VERSION}.js`);try{fm.writeString(b,fm.readString(target))}catch(_){}fm.writeString(target,src);return{ok:true,text:`Updated to v${v}. Run script again.`}}catch(e){return{ok:false,text:`Update error: ${String(e?.message||e)}`}}}

let SETTINGS=await firstLanguage(loadSettings());
const PREVIEW_FAMILY=String(args.queryParameters?.sportsPreview||"");
if(config.runsInWidget)Script.setWidget(await widget(SETTINGS,config.widgetFamily||"medium"));
else if(["small","medium","large"].includes(PREVIEW_FAMILY)){const w=await widget(SETTINGS,PREVIEW_FAMILY);if(PREVIEW_FAMILY==="small")await w.presentSmall();else if(PREVIEW_FAMILY==="large")await w.presentLarge();else await w.presentMedium();await settings(SETTINGS)}
else await settings(SETTINGS);
Script.complete();
